    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    out = []
    slot = {}
    from_primary = {}

    all_records = [(rec, True) for rec in primary] + [(rec, False) for rec in incoming]

    for rec, is_primary in all_records:
        email = rec["email"].lower()
        if email in slot:
            i = slot[email]
            existing = out[i]
            existing_is_primary = from_primary[i]

            rich_rec = sum(1 for v in rec.values() if v not in (None, ""))
