newString: def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    from datetime import datetime

    out = []
    slot = {}

    combined = [(rec, True) for rec in primary] + [(rec, False) for rec in incoming]

    for rec, is_primary in combined:
        dt = datetime.fromisoformat(rec["updated"])
        key = (rec["email"].lower(), dt.date())

        non_empty_count = sum(1 for v in rec.values() if v is not None and v != "")

        if key in slot:
            i, existing_is_primary, existing_count = slot[key]

            replace = False
            if non_empty_count > existing_count:
                replace = True
            elif non_empty_count < existing_count:
                replace = False
            else:
                if is_primary and not existing_is_primary:
                    replace = True

            if replace:
                out[i] = rec
                slot[key] = (i, is_primary, non_empty_count)
        else:
            slot[key] = (len(out), is_primary, non_empty_count)
            out.append(rec)

    return out
