newString: """Egress allowlist matching."""
import ipaddress


def is_ip_address(s):
    try:
        ipaddress.ip_address(s)
        return True
    except ValueError:
        return False


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    if not host:
        return False

    if is_ip_address(host):
        host_ip = ipaddress.ip_address(host)
        for entry in allowlist:
            if not entry:
                continue
            if is_ip_address(entry):
                if host_ip == ipaddress.ip_address(entry):
                    return True
        return False

    host_parts = [p for p in host.lower().split('.') if p]

    for entry in allowlist:
        if not entry:
            continue

        if is_ip_address(entry):
            continue

        entry_parts = [p for p in entry.lower().split('.') if p]

        if entry.startswith("*."):
            if len(entry_parts) > 0 and entry_parts[0] == '*':
                if len(host_parts) == len(entry_parts):
                    if host_parts[1:] == entry_parts[1:]:
                        return True
        else:
            if host_parts == entry_parts:
                return True

    return False

