filePath: /work/logsafe/redact.py
content: """Redact sensitive fields from log events."""

import re
import collections.abc


def normalize_key(key):
    if not isinstance(key, str):
        return ""
    # Convert to lowercase
    k = key.lower()
    # Replace all non-alphanumeric character sequences with underscores
    k = re.sub(r'[^a-z0-9]+', '_', k)
    # Strip leading/trailing underscores
    k = k.strip('_')
    return k


def _redact(val):
    if isinstance(val, collections.abc.Mapping):
        out = {}
        for k, v in val.items():
            norm_k = normalize_key(k) if isinstance(k, str) else ""
            if norm_k.endswith("email"):
                out[k] = _redact(v)
            elif (
                norm_k.endswith("password")
                or norm_k.endswith("token")
                or norm_k.endswith("api_key")
                or norm_k.endswith("ssn")
            ):
                out[k] = "***"
            elif norm_k.endswith("card_number"):
                if v is None:
                    out[k] = "***"
                else:
                    out[k] = "***" + str(v)[-4:]
            else:
                out[k] = _redact(v)
        return out
    elif isinstance(val, list):
        return [_redact(item) for item in val]
    elif isinstance(val, tuple):
        return tuple(_redact(item) for item in val)
    elif isinstance(val, set):
        return {_redact(item) for item in val}
    else:
        return val


def redact(event):
    """Mask sensitive fields in a log event."""
    return _redact(event)

