filePath: /work/jobsched/picker.py
content: """Job queue picker."""


def next_job(queue, last_tenant):
    """Pick the next job to run from the queue."""
    if not queue:
        return None

    # Check if other tenants have pending jobs
    has_other_tenants = any(j["tenant"] != last_tenant for j in queue)
    if has_other_tenants:
        eligible_jobs = [j for j in queue if j["tenant"] != last_tenant]
    else:
        eligible_jobs = queue

    return min(
        eligible_jobs,
        key=lambda j: (-j["priority"], j["est_runtime"], j["submitted_at"])
    )

