content: """SLA downtime accounting."""
from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    if not incidents:
        return 0.0

    # 1. Parse incident intervals
    parsed_incidents = []
    for inc in incidents:
        parsed_incidents.append((_t(inc["start"]), _t(inc["end"])))

    # 2. Merge overlapping or touching incident intervals
    parsed_incidents.sort(key=lambda x: x[0])
    merged_incidents = []
    for current in parsed_incidents:
        if not merged_incidents:
            merged_incidents.append(current)
        else:
            prev_start, prev_end = merged_incidents[-1]
            curr_start, curr_end = current
            if curr_start <= prev_end:
                merged_incidents[-1] = (prev_start, max(prev_end, curr_end))
            else:
                merged_incidents.append(current)

    # 3. Filter out merged windows that are under 60 seconds (noise)
    filtered_incidents = []
    for start, end in merged_incidents:
        if (end - start).total_seconds() >= 60.0:
            filtered_incidents.append((start, end))

    if not filtered_incidents:
        return 0.0

    # 4. Filter and parse valid maintenance windows
    valid_maintenances = []
    for m in maintenance:
        m_start = _t(m["start"])
        m_end = _t(m["end"])
        if "announced_at" in m:
            m_announced = _t(m["announced_at"])
            if m_start - m_announced < timedelta(hours=24):
                # Not eligible to be excluded
                continue
        valid_maintenances.append((m_start, m_end))

    # 5. Merge overlapping/touching maintenance windows to avoid double subtraction
    merged_maintenances = []
    if valid_maintenances:
        valid_maintenances.sort(key=lambda x: x[0])
        for current in valid_maintenances:
            if not merged_maintenances:
                merged_maintenances.append(current)
            else:
                prev_start, prev_end = merged_maintenances[-1]
                curr_start, curr_end = current
                if curr_start <= prev_end:
                    merged_maintenances[-1] = (prev_start, max(prev_end, curr_end))
                else:
                    merged_maintenances.append(current)

    # 6. For each filtered incident interval, calculate total downtime minus maintenance overlap
    total_downtime_seconds = 0.0
    for inc_start, inc_end in filtered_incidents:
        incident_seconds = (inc_end - inc_start).total_seconds()

        for maint_start, maint_end in merged_maintenances:
            lo = max(inc_start, maint_start)
            hi = min(inc_end, maint_end)
            overlap_seconds = max((hi - lo).total_seconds(), 0.0)
            incident_seconds -= overlap_seconds

        total_downtime_seconds += max(incident_seconds, 0.0)

    return total_downtime_seconds / 60.0

