newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    out = []
    seen_lower = set()
    active_tombstones_lower = set()

    for tags in sources:
        current_tombstones_lower = set()
        for tag in tags:
            if tag.startswith('-'):
                current_tombstones_lower.add(tag[1:].lower())
            else:
                tag_lower = tag.lower()
                if tag_lower in active_tombstones_lower:
                    continue
                if tag_lower in seen_lower:
                    continue
                out.append(tag)
                seen_lower.add(tag_lower)
        active_tombstones_lower.update(current_tombstones_lower)
    return out
