filePath: /work/labelsync/tags.py
newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    out = []
    seen = set()
    active_tombstones = set()
    for tags in sources:
        for tag in tags:
            if tag.startswith('-'):
                continue
            tag_lower = tag.lower()
            if tag_lower in active_tombstones:
                continue
            if tag_lower in seen:
                continue
            out.append(tag)
            seen.add(tag_lower)
        for tag in tags:
            if tag.startswith('-'):
                active_tombstones.add(tag[1:].lower())
    return out

