newString: """Config quantity parsing for the provisioning pipeline."""


def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty quantity")

    kind_lower = str(kind).lower()
    if s[-1].isalpha():
        suffix = s[-1].upper()
        if kind_lower == "memory":
            allowed = {"K", "M", "G", "T"}
        elif kind_lower == "disk":
            allowed = {"M", "G", "T"}
        else:
            raise ValueError("unknown resource kind: " + str(kind))

        if suffix not in allowed:
            raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])

        num_part = s[:-1]
        val = int(num_part)

        if kind_lower == "memory":
            mults = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3, "T": 1024 ** 4}
        else:
            mults = {"M": 1000 ** 2, "G": 1000 ** 3, "T": 1000 ** 4}

        return val * mults[suffix]
    else:
        val = int(s)
        if kind_lower == "memory":
            return val * (1024 ** 2)
        elif kind_lower == "disk":
            return val * (1000 ** 3)
        else:
            raise ValueError("unknown resource kind: " + str(kind))
